   800	UA_Server_removeConnection(UA_Server *server, UA_Connection *connection) {
   801	    UA_Connection_detachSecureChannel(connection);
   802	#ifndef UA_ENABLE_MULTITHREADING
   803	    connection->free(connection);
   804	#else
   805	    UA_DelayedCallback *dc = (UA_DelayedCallback*)UA_malloc(sizeof(UA_DelayedCallback));
   806	    if(!dc)
   807	        return; /* Malloc cannot fail on OS's that support multithreading. They
   808	                 * rather kill the process. */
   809	    dc->callback = (UA_ApplicationCallback)deleteConnection;
   810	    dc->application = server;
   811	    dc->data = connection;
   812	    UA_WorkQueue_enqueueDelayed(&server->workQueue, dc);
